"""Comparing what the websites show: dates and attribute values (plain code, no model, no scenario values).

The rules the brief states are almost all of two shapes — "the latest record no later than the scenario date"
and "every attribute exactly equal" — and both break on presentation rather than on meaning: a date is written
in three notations across the four sites, and a value that looks equal differs by an invisible character, a
unit suffix or a decimal comma. The model finds the records; these functions decide which one is newer and
whether two values are the same.
"""
from __future__ import annotations

import re
from datetime import date, datetime
from decimal import InvalidOperation

from swarm.bidmath import D, plain

ISO = re.compile(r"(\d{4})-(\d{2})-(\d{2})")
DOTTED = re.compile(r"(\d{1,2})[.](\d{1,2})[.](\d{4})")
SLASHED = re.compile(r"(\d{1,2})/(\d{1,2})/(\d{4})")
NUMBER = re.compile(r"-?\d[\d.,\s]*")


def parse_date(text, dayfirst: bool = True) -> date | None:
    """The date in what a page shows, or None.

    ISO first, because it is unambiguous and the sites put it in tooltips and `datetime` attributes next to the
    human-readable date. `TT.MM.JJJJ` is German and always day-first; a slashed date is ambiguous and follows
    `dayfirst`, which the caller takes from the tag the page prints beside it.
    """
    text = plain(text)
    if not text:
        return None
    if found := ISO.search(text):
        year, month, day = (int(g) for g in found.groups())
    elif found := DOTTED.search(text):
        day, month, year = (int(g) for g in found.groups())
    elif found := SLASHED.search(text):
        first, second, year = (int(g) for g in found.groups())
        day, month = (first, second) if dayfirst else (second, first)
    else:
        return None
    try:
        return date(year, month, day)
    except ValueError:
        return None


def parse_moment(text) -> datetime | None:
    """A date with its time when the page shows one, for ordering records written on the same day."""
    text = plain(text)
    try:
        return datetime.fromisoformat(text.replace("Z", "+00:00"))
    except ValueError:
        pass
    day = parse_date(text)
    if day is None:
        return None
    clock = re.search(r"(\d{1,2}):(\d{2})(?::(\d{2}))?", text)
    hour, minute, second = (int(g or 0) for g in clock.groups()) if clock else (0, 0, 0)
    try:
        return datetime(day.year, day.month, day.day, hour, minute, second)
    except ValueError:
        return datetime(day.year, day.month, day.day)


def not_after(when, limit) -> bool:
    """True when `when` is on or before `limit` (both as the pages write them). Unknown dates never qualify:
    "no later than the scenario date" has to be shown, not assumed."""
    a, b = parse_date(when), parse_date(limit)
    return bool(a and b and a <= b)


def as_number(value):
    """The number in a value as shown ('210 mm', '12,5 %', '1.234,56'), or None when it is not numeric."""
    text = plain(value)
    if not text:
        return None
    found = NUMBER.search(text.replace(" ", " "))
    if not found:
        return None
    try:
        return D(found.group(0))
    except (InvalidOperation, ValueError, ArithmeticError):
        return None


def same_value(left, right) -> bool:
    """Whether two attribute values are the same value (rule 3 wants exact equality, not similarity).

    Numbers compare as numbers, so `210`, `210,0` and `210 mm` are one value and 210 never equals 2100; text
    compares without invisible padding, case or spacing. A number on one side and text on the other is not
    equal: that is a unit or a label mismatch, which is exactly what the rule is about.
    """
    a, b = plain(left), plain(right)
    if not a or not b:
        return False
    a_num, b_num = as_number(a), as_number(b)
    if (a_num is None) != (b_num is None):
        return False
    if a_num is not None and b_num is not None:
        if a_num != b_num:
            return False
        # '210 mm' vs '210 bar': the numbers agree, the units have to as well
        return _unit(a) == _unit(b)
    return a.casefold() == b.casefold()


def _unit(text: str) -> str:
    """What is left of a value once its number is removed, folded: the unit or suffix, if any."""
    return NUMBER.sub(" ", plain(text)).replace(" ", "").casefold()


def attributes_match(required: dict, candidate: dict) -> tuple[bool, list[str]]:
    """Every required attribute equal in the candidate; returns (match, the attributes that differ or are missing).

    Only the attributes the requirement names are compared: an ERP material carries more fields than a
    specification asks for, and extra fields are not a mismatch.
    """
    differs = []
    for key, want in required.items():
        if want is None or plain(want) == "":
            continue
        have = candidate.get(key)
        if have is None or not same_value(want, have):
            differs.append(key)
    return (not differs), differs

