# OWNER: (name)   ROLE: calculator (plain code, no model)
# NEEDS: results["quantities"], results["materials"], results["commercials"], results["discount"], results["requirements"]
# WRITES: results["bid"], results["answer"]
"""The bid, computed from what the analyzers decided. No model call, no website: arithmetic only.

results["bid"] = the answer object (tender_reference, decision, currency, discount_percent, positions,
total_net) as `swarm.bidmath.answer` builds it, with each position carrying "attributes" for the
configurator. results["answer"] is the same object, for a run that takes its answer through the API.

Order matters and follows the brief: base unit price per position first (it decides the discount threshold),
then the order discount, then delivery from the pooled demand per material, then one rounding per unit price
and one for the total. A position whose facts are incomplete is left out rather than guessed - an omitted
position costs its own points, a wrong one costs the same and can make the total wrong as well.
"""
from swarm import Agent, Phase, register
from swarm.bidmath import (Bid, D, PositionFacts, Scale, ZERO, answer, base_unit_price_eur, lead_time_weeks,
                           order_discount, plain, undiscounted_net)


@register
class BidCalculator(Agent):
    phase = Phase.COMPUTE

    async def run(self) -> None:
        board = self.ctx.board
        case = await self.ctx.case()
        quantities = board.get("quantities") or {}
        materials = board.get("materials") or {}
        commercials = board.get("commercials") or {}
        requirements = (board.get("requirements") or {}).get("positions") or {}
        discount = board.get("discount") or {}
        reference = plain(case.get("tender_reference")) or self.reference_from_evidence()

        priced, skipped = self.price_each(quantities, materials, commercials)
        decision = self.decide(quantities, materials, requirements)
        percent = self.discount_percent(discount, priced, decision)
        for facts in priced.values():
            facts.lead_time_weeks = self.delivery(facts, priced, commercials)

        bid = Bid(tender_reference=reference, decision=decision, discount_percent=percent,
                  positions=[priced[p] for p in sorted(priced)])
        out = answer(bid)
        for entry in out["positions"]:
            attributes = (requirements.get(entry["position"]) or {}).get("attributes")
            if attributes:
                entry["attributes"] = attributes
        await board.set("bid", out)
        await board.set("answer", out)
        self.log.info("%s: %d position(s), %s %% discount, total %s; left out: %s", decision, len(out["positions"]),
                      out["discount_percent"], out["total_net"], skipped or "none")

    # --- the parts -----------------------------------------------------------------------------------------

    def price_each(self, quantities: dict, materials: dict, commercials: dict) -> tuple[dict, list[str]]:
        """A PositionFacts per position that has everything it needs; the rest are reported as left out."""
        priced, skipped = {}, []
        for position in sorted(set(quantities) | set(materials)):
            try:
                priced[position] = self.one(position, quantities, materials, commercials)
            except Exception as error:  # noqa: BLE001 - a position without facts is omitted, the bid still goes
                skipped.append(f"{position} ({error})")
                self.log.warning("position %s left out: %s", position, error)
        return priced, skipped

    def one(self, position: str, quantities: dict, materials: dict, commercials: dict) -> PositionFacts:
        quantity = quantities.get(position) or {}
        material = materials.get(position) or {}
        commercial = commercials.get(position) or {}
        pieces = int(quantity.get("pieces") or 0)
        if pieces <= 0:
            raise ValueError("no final quantity")
        if not material.get("ok") or not material.get("material_number"):
            raise ValueError(material.get("reason") or "no matching active material")
        scales = [Scale(min_quantity=int(s["min_quantity"]), price=s["price"]) for s in commercial.get("scales") or []]
        if not scales:
            raise ValueError("no valid price condition")
        base = base_unit_price_eur(scales, pieces, commercial.get("price_unit") or 1,
                                   self.eur_per_unit(commercial))
        return PositionFacts(
            position=position, material_number=plain(material["material_number"]), pieces=pieces,
            base_unit_price=base, lead_time_weeks=0,            # set once every position's demand is known
            surcharge_per_piece=D(commercial["surcharge_per_piece"]) if commercial.get("surcharge_per_piece") else ZERO,
            setup_fee=D(commercial["setup_fee"]) if commercial.get("setup_fee") else ZERO)

    @staticmethod
    def eur_per_unit(commercial: dict):
        """EUR per one unit of the condition's currency: 1 for EUR, else the fixing the analyzer reported."""
        currency = plain(commercial.get("currency")).upper()
        rate = commercial.get("eur_per_currency_unit")
        if currency in ("", "EUR", "€"):
            return 1
        if not rate:
            raise ValueError(f"price is in {currency} and no fixing was found")
        return rate

    def decide(self, quantities: dict, materials: dict, requirements: dict) -> str:
        """no_bid when a position of this tender has no active matching material (rule 3 + 8)."""
        known = set(quantities) | set(materials) | set(requirements)
        for position in known:
            entry = materials.get(position)
            if entry is None or not entry.get("ok"):
                self.log.info("no_bid: position %s has no matching active material (%s)", position,
                              (entry or {}).get("reason") or "not analyzed")
                return "no_bid"
        return "bid" if known else "no_bid"

    def discount_percent(self, discount: dict, priced: dict, decision: str):
        """The approved percentage, kept only when its minimum net order value is reached (rule 5 + its refinement)."""
        net = undiscounted_net([(facts.pieces, facts.base_unit_price) for facts in priced.values()])
        percent = order_discount(discount.get("percent") or 0, discount.get("threshold"), net, decision)
        if discount.get("threshold") is not None:
            self.log.info("conditional approval: undiscounted net %s against threshold %s -> %s %%",
                          net, discount["threshold"], percent)
        return percent

    @staticmethod
    def delivery(facts: PositionFacts, priced: dict, commercials: dict) -> int:
        """Stock is all-or-nothing per material: every position selecting it shares the same pooled demand (rule 15)."""
        commercial = commercials.get(facts.position) or {}
        pooled = sum(other.pieces for other in priced.values() if other.material_number == facts.material_number)
        stock = commercial.get("stock_pieces")
        from_stock = commercial.get("stock_lead_time_weeks")
        production = commercial.get("production_lead_time_weeks")
        if stock is None or from_stock is None or production is None:
            return int(production if production is not None else (from_stock or 0))
        return lead_time_weeks(int(stock), pooled, int(from_stock), int(production))

    def reference_from_evidence(self) -> str:
        """The brief states the reference; if it could not be read, the tender's own page did (eligibility
        depends on it, so an empty one is worth one more look)."""
        for item in self.ctx.board.query("tender.meta", prefix=True):
            for key, value in (item.data or {}).items():
                if "referen" in str(key).casefold() or "vergabenummer" in str(key).casefold():
                    return plain(value)
        return ""

