# OWNER: (name)   ROLE: verifier   NEEDS: all results   WRITES: results["verification"]
"""Cross-checks the analyzers' results against the evidence, before anything is priced.

results["verification"] = {"warnings": [str],    # what looks wrong, most important first
                           "checked": {str: bool}}

It never drops a position and never rewrites a value: a verifier that silently removes work turns a scoring
mistake into a missing position, which costs more. It states what is inconsistent, so the calculator's own
degrade path (omit what cannot be computed) and a reader of the logs both see the same thing.
"""
from swarm import Agent, Phase, register
from swarm.bidmath import plain
from swarm.facts import not_after

MAX_WARNINGS = 20


@register
class EvidenceVerifier(Agent):
    phase = Phase.VERIFY

    async def run(self) -> None:
        board = self.ctx.board
        case = await self.ctx.case()
        reference = plain(case.get("tender_reference"))
        scenario = case.get("scenario_date")
        quantities = board.get("quantities") or {}
        materials = board.get("materials") or {}
        commercials = board.get("commercials") or {}
        requirements = (board.get("requirements") or {}).get("positions") or {}
        discount = board.get("discount") or {}

        warnings = []
        if not reference:
            warnings.append("the tender reference could not be read from the brief: the bid is ineligible without it")
        if not quantities:
            warnings.append("no quantities were resolved")
        if not requirements:
            warnings.append("no requirements were resolved: materials cannot have been matched against anything")

        for position in sorted(set(quantities) | set(requirements) | set(materials)):
            warnings += self.position_warnings(position, quantities, requirements, materials, commercials)

        if discount.get("percent"):
            if scenario and discount.get("date") and not not_after(discount["date"], scenario):
                warnings.append(f"the discount is dated {discount['date']}, after the scenario date")
            if not discount.get("source"):
                warnings.append("the discount has no source: it cannot be traced to an approval")

        result = {"warnings": warnings[:MAX_WARNINGS],
                  "checked": {"reference": bool(reference), "quantities": bool(quantities),
                              "requirements": bool(requirements), "materials": bool(materials),
                              "commercials": bool(commercials), "discount": "percent" in discount}}
        await board.set("verification", result)
        for warning in result["warnings"]:
            self.log.warning("%s", warning)

    @staticmethod
    def position_warnings(position: str, quantities: dict, requirements: dict, materials: dict,
                          commercials: dict) -> list[str]:
        out = []
        quantity = quantities.get(position) or {}
        material = materials.get(position) or {}
        commercial = commercials.get(position) or {}
        if not quantity.get("pieces"):
            out.append(f"position {position}: no final quantity")
        if position in requirements and not material.get("analyzed"):
            out.append(f"position {position}: a requirement but no material was reported")
        if material.get("material_number") and not material.get("ok"):
            out.append(f"position {position}: {material.get('reason') or 'the candidate material does not match'}")
        if material.get("ok") and not commercial.get("scales"):
            out.append(f"position {position}: a material but no valid price condition")
        if commercial.get("material_number") and material.get("material_number") \
                and plain(commercial["material_number"]) != plain(material["material_number"]):
            out.append(f"position {position}: the price condition is for material "
                       f"{commercial['material_number']}, the position selected {material['material_number']}")
        if commercial.get("scales") and commercial.get("currency", "").upper() not in ("", "EUR", "€") \
                and not commercial.get("eur_per_currency_unit"):
            out.append(f"position {position}: price in {commercial['currency']} without a fixing to convert it")
        return out

