def discount_check(self, discount: dict, priced: dict, tender: set, decision: str) -> dict:
    """The approved percentage, kept only when its minimum net order value is reached (rule 5 + its refinement).

    The order value is summed over every position whose base price is known. When some are not, the sum
    is short by their value, and the check can only go one way with certainty: prices are never negative,
    so a threshold reached without them is reached with them. One that is not reached is undecided rather
    than failed. The brief's answer to a failed condition - zero, with no fallback to an older approval -
    is kept for that case too, but it is reported as undecided, because it may be the wrong one.
    """
    approved, threshold = discount.get("percent") or 0, discount.get("threshold")
    net = undiscounted_net([(facts.pieces, facts.base_unit_price) for facts in priced.values()])
    percent = order_discount(approved, threshold, net, decision)
    unknown = sorted(tender - set(priced))
    check = {"approved": float(D(approved)), "threshold": threshold, "net": float(net),
             "percent": float(percent), "unpriced_positions": unknown,
             "decided": threshold is None or decision != "bid" or percent > 0 or not unknown}
    if threshold is not None and not check["decided"]:
        self.log.warning("discount threshold undecided: net %s of the positions priced is below %s, and %s "
                         "have no price; using 0 %% as for a failed condition", net, threshold, ", ".join(unknown))
    elif threshold is not None:
        self.log.info("conditional approval: undiscounted net %s against threshold %s -> %s %%",
                      net, threshold, percent)
    return check

@staticmethod
def demand(quantities: dict, materials: dict) -> dict:
    """Final pieces per material, over EVERY position that selected it (rule 15).

    Not only the positions in the bid: one left out for a missing price still selects its material, and
    its pieces still have to come out of the same stock. Counting only the priced positions under-states
    the demand and can turn a production delivery into a stock delivery.
    """
    out = {}
    for position, material in materials.items():
        number = plain(material.get("material_number"))
        pieces = (quantities.get(position) or {}).get("pieces")
        if material.get("ok") and number and pieces:
            out[number] = out.get(number, 0) + int(pieces)
    return out

def delivery(self, facts: PositionFacts, demand: dict, priced: dict, commercials: dict) -> tuple[int, bool]:
    """Lead time in weeks and whether it is established (True) or the best available guess (False).

    Stock is all-or-nothing per material against the pooled demand (rule 15 + 6). Many incomplete readings
    still have an exact answer: when stock covers the demand the production time does not matter, and
    when it does not, the stock time does not. Only what remains is a guess, and it is logged as one.
    """
    stock, from_stock, production = self.stock_facts(facts, priced, commercials)
    pooled = demand.get(facts.material_number, facts.pieces)
    covers = None if stock is None else stock_covers(int(stock), pooled)
    if covers is True and from_stock is not None:
        return int(from_stock), True
    if covers is False and production is not None:
        return int(production), True
    # production is what can always be promised: delivery from stock is the exception that has to be shown
    guess = next((int(value) for value in (production, from_stock) if value is not None), 0)
    self.log.warning("position %s: lead time not established (stock %s, pooled demand %s, from stock %s, "
                     "production %s); entering %s weeks", facts.position, stock, pooled, from_stock,
                     production, guess)
    return guess, False

@staticmethod
def stock_facts(facts: PositionFacts, priced: dict, commercials: dict) -> tuple:
    """Stock and both lead times of the position's material.

    They belong to the material, not to the position, so a value this position's reading lacks is taken
    from another position that selected the same material (in position order, for a stable result).
    """
    own = commercials.get(facts.position) or {}
    known = {key: own.get(key) for key in STOCK_FIELDS}
    for other in sorted(priced):
        if other == facts.position or priced[other].material_number != facts.material_number:
            continue
        sibling = commercials.get(other) or {}
        for key in STOCK_FIELDS:
            if known[key] is None and sibling.get(key) is not None:
                known[key] = sibling[key]
    return tuple(known[key] for key in STOCK_FIELDS)

