"""A saved blackboard, summarised for a person: what each website gave, who used whose findings, what was decided.

    uv run --no-sync python -m swarm.report                      # .swarm/board.json
    uv run --no-sync python -m swarm.report .swarm/board.tender.json --samples 5

Made for staged local runs: scrape one website with SWARM_ONLY, keep the board, start the next stage from it
with SWARM_BOARD_IN, and read each stage's board with this. A development tool only - it reads a local file and
prints it; the run itself never imports it. The boards hold scouting data: they stay in .swarm/ (git-ignored).
"""
from __future__ import annotations

import argparse
import json
from collections import Counter, defaultdict
from pathlib import Path

WIDTH = 110


def short(value, width: int = WIDTH) -> str:
    text = value if isinstance(value, str) else json.dumps(value, ensure_ascii=False, default=str)
    text = " ".join(text.split())
    return text if len(text) <= width else text[: width - 1] + "…"


def section(title: str) -> None:
    print(f"\n== {title} " + "=" * max(0, WIDTH - len(title) - 4))


def evidence(board: dict, samples: int) -> None:
    items = board.get("evidence") or []
    section(f"Evidence: {len(items)} record(s)")
    if not items:
        print("  nothing was recorded")
        return
    by_site = defaultdict(list)
    for item in items:
        by_site[item.get("site") or "?"].append(item)
    for site in sorted(by_site):
        records = by_site[site]
        authors = ", ".join(sorted({r.get("author") or "?" for r in records}))
        print(f"\n  {site}  ({len(records)} record(s), by {authors})")
        kinds = Counter(r.get("kind") or "?" for r in records)
        for kind, count in sorted(kinds.items()):
            print(f"    {count:3}  {kind}")
            for record in [r for r in records if r.get("kind") == kind][:samples]:
                print(f"           data   {short(record.get('data'), WIDTH - 18)}")
                if record.get("source"):
                    print(f"           from   {short(record['source'], WIDTH - 18)}")
                if record.get("note"):
                    print(f"           note   {short(record['note'], WIDTH - 18)}")


def talk(board: dict) -> None:
    calls = (board.get("results") or {}).get("talk") or []
    section(f"Cross-talk: {len(calls)} call(s) to read or wait for other agents' findings")
    if not calls:
        print("  no agent asked the board for anything")
        return
    for call in calls:
        came = f"{call.get('returned', 0)} record(s) from {', '.join(call.get('from_sites') or []) or 'nobody'}"
        print(f"  {call.get('at', 0):7.1f}s  {call.get('agent', '?'):14} {call.get('action', '?'):18} "
              f"{(call.get('kind') or '(any)'):24} -> {came}")
    empty = [c for c in calls if not c.get("returned")]
    used = Counter((c.get("agent"), site) for c in calls for site in c.get("from_sites") or [])
    print("\n  used findings from:", ", ".join(f"{a} <- {s} ({n}x)" for (a, s), n in sorted(used.items())) or "none")
    if empty:
        print(f"  {len(empty)} call(s) came back empty: asked before the finding existed, or for a kind nobody records")


def results(board: dict) -> None:
    res = board.get("results") or {}
    shown = {k: v for k, v in res.items() if k != "talk" and not k.endswith(".summary")}
    section(f"Results: {', '.join(sorted(shown)) or 'none'}")
    for key in ("quantities", "requirements", "materials", "commercials", "discount", "verification",
                "calculation", "bid"):
        if key in shown:
            print(f"  {key:13} {describe(key, shown[key])}")
    for key in sorted(set(shown) - {"quantities", "requirements", "materials", "commercials", "discount",
                                    "verification", "calculation", "bid", "answer"}):
        print(f"  {key:13} {short(shown[key], WIDTH - 16)}")
    summaries = {k[: -len(".summary")]: v for k, v in res.items() if k.endswith(".summary")}
    if summaries:
        section("What each browsing agent said when it finished")
        for agent, text in sorted(summaries.items()):
            print(f"  {agent}: {short(text or '(no summary)', WIDTH - len(agent) - 4)}")


def describe(key: str, value) -> str:
    """One line per result, saying what matters about it rather than dumping it."""
    try:
        if key == "quantities":
            return f"{len(value)} position(s): " + short({p: v.get("pieces") for p, v in value.items()}, 80)
        if key == "requirements":
            positions = value.get("positions") or {}
            return f"revision {value.get('revision', {}).get('id') or '?'}, {len(positions)} position(s) with " \
                   f"{sum(1 for p in positions.values() if p.get('attributes'))} attribute set(s)"
        if key == "materials":
            ok = sum(1 for m in value.values() if m.get("ok"))
            looked = sum(1 for m in value.values() if m.get("analyzed"))
            return f"{ok} matched / {looked} analyzed / {len(value)} position(s)"
        if key == "commercials":
            return f"{sum(1 for c in value.values() if c.get('scales'))} of {len(value)} position(s) with a price condition"
        if key == "discount":
            return f"{value.get('percent')} %, threshold {value.get('threshold')}, from {value.get('sender') or 'nobody'}"
        if key == "verification":
            warnings = value.get("warnings") or []
            return f"{len(warnings)} warning(s)" + (f": {short(warnings[0], 70)}" if warnings else "")
        if key == "calculation":
            check = value.get("discount") or {}
            return (f"discount check {'decided' if check.get('decided', True) else 'UNDECIDED'}, "
                    f"lead time guessed for {value.get('lead_time_guessed') or 'none'}, "
                    f"left out {len(value.get('left_out') or [])}")
        if key == "bid":
            return (f"{value.get('decision')} {value.get('tender_reference')!r}: {len(value.get('positions') or [])} "
                    f"position(s), {value.get('discount_percent')} %, total {value.get('total_net')}")
    except (AttributeError, TypeError):
        pass
    return short(value, WIDTH - 16)


def errors(board: dict) -> None:
    errs = board.get("errors") or []
    if errs:
        section(f"Errors: {len(errs)}")
        for err in errs:
            print(f"  {err.get('agent', '?')}: {short(err.get('error'), WIDTH - 20)}")


def main(argv=None) -> int:
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument("board", nargs="?", default=".swarm/board.json")
    parser.add_argument("--samples", type=int, default=2, help="records shown per kind (default 2)")
    args = parser.parse_args(argv)
    path = Path(args.board)
    if not path.exists():
        print(f"no board at {path}: run the swarm locally first (it saves one after every phase)")
        return 1
    board = json.loads(path.read_text(encoding="utf-8"))
    print(f"board {path}  ({path.stat().st_size // 1024} KB)")
    evidence(board, args.samples)
    talk(board)
    results(board)
    errors(board)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
